export function translate(language: LanguageCode, key: TranslationKey): string {
  return translations[language]?.[key] ?? translations.es[key] ?? key
}

// BUG CORREGIDO: varias pantallas formateaban fechas con `toLocaleDateString("es-ES", ...)`
// fijo, sin importar el idioma activo — una pantalla ya traducida a inglés seguía
// mostrando "22 de agosto de 2026" en vez de "August 22, 2026". Este mapeo se usa en
// vez del código de idioma corto (que Intl no acepta de forma fiable para todos los
// casos) para pasar a `toLocaleDateString`/`toLocaleString`.
const DATE_LOCALES: Record<LanguageCode, string> = {
  es: "es-ES",
  en: "en-US",
  da: "da-DK",
  fr: "fr-FR",
  pt: "pt-BR",
  zh: "zh-CN",
}

export function getDateLocale(language: LanguageCode): string {
  return DATE_LOCALES[language] || DATE_LOCALES.es
}

export default translations
